script:
now_dt = frappe.utils.now_datetime()

# =========================================================
# SECTION 1 — CHECK-IN VALIDATIONS (runs only when new doc)
# =========================================================
if doc.is_new():

    # Validation 1: log_type must be IN
    if doc.log_type != "IN":
        frappe.throw("Log Type must be 'IN' when creating a new check-in record.")

    # Validation 2: Check-in time cannot be in future
    checkin_time = frappe.utils.get_datetime(doc.time)
    if checkin_time > now_dt:
        frappe.throw("Check-in Time cannot be set in the future.")

    # Validation 3: Duplicate check-in same day
    checkin_date = frappe.utils.getdate(doc.time)

    existing = frappe.db.get_value(
        "Employee Checkin",
        {
            "employee": doc.employee,
            "log_type": "IN",
            "time": ["between", [
                str(checkin_date) + " 00:00:00",
                str(checkin_date) + " 23:59:59"
            ]]
        },
        "name"
    )

    if existing:
        frappe.throw(
            "Employee {0} already has a Check-in record for {1}. Only one check-in per day is allowed.".format(
                doc.employee_name or doc.employee,
                checkin_date
            )
        )

# =========================================================
# SECTION 2 — CHECKOUT VALIDATIONS
# =========================================================

if doc.log_type_out == "OUT":

    # Validation 4: OUT requires IN
    if doc.log_type != "IN":
        frappe.throw("Cannot mark Check-out. This record does not have a valid Check-in (Log Type: IN).")

    # Validation 5: checkout_time required
    if not doc.checkout_time:
        frappe.throw("Checkout Time is required when Log Type Out is 'OUT'.")

    checkin_time = frappe.utils.get_datetime(doc.time)
    checkout_time = frappe.utils.get_datetime(doc.checkout_time)

    # Validation 6: checkout after checkin
    if checkout_time <= checkin_time:
        frappe.throw(
            "Checkout Time ({0}) must be after Check-in Time ({1}).".format(
                doc.checkout_time, doc.time
            )
        )

    # Validation 7: prevent double checkout
    if not doc.is_new():
        old_checkout = frappe.db.get_value("Employee Checkin", doc.name, "checkout_time")
        if old_checkout:
            frappe.throw(
                "Employee {0} has already checked out at {1}. Cannot update checkout again.".format(
                    doc.employee_name or doc.employee,
                    old_checkout
                )
            )

    # Validation 8: checkout not future
    if checkout_time > now_dt:
        frappe.throw("Checkout Time cannot be set in the future.")

# =========================================================
# SECTION 3 — Checkout time entered but log_type_out missing
# =========================================================
if doc.checkout_time and doc.log_type_out != "OUT":
    frappe.throw("You entered Checkout Time but Log Type Out is not set to 'OUT'.")

# get today's date
today_date = frappe.utils.getdate(frappe.utils.today())

# check from_date
if doc.from_date:
    if frappe.utils.getdate(doc.from_date) < today_date:
        frappe.throw("Leave cannot be applied for past dates. Please select today or future date.")

# check to_date
if doc.to_date:
    if frappe.utils.getdate(doc.to_date) < today_date:
        frappe.throw("To Date cannot be in the past. Please select today or future date.")

if doc.workflow_state == "Approved":
    frappe.db.set_value("Employee", doc.employee, {
        "status": "Left",
        "relieving_date": doc.boarding_begins_on
        # replace 'doc.relieving_date' with your actual field name
    })
    frappe.msgprint(f"Employee {doc.employee_name} has been marked as Left")
